20), "Local" NVARCHAR(2), "UseSysPref" NVARCHAR(1) DEFAULT 'Y', "ForMobile" NVARCHAR(1) DEFAULT 'Y', "TypeDetail" NVARCHAR(254), "IsIMCE" NVARCHAR(1) DEFAULT 'N', "CsUrl" NVARCHAR(254), "RptHash" NVARCHAR(254), PRIMARY KEY ("DocCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
